function applyCategoryImages() {
  document.querySelectorAll("[data-cat-img]").forEach(img => {
    const key = img.getAttribute("data-cat-img");
    if (CATEGORY_IMAGES && CATEGORY_IMAGES[key]) {
      img.src = CATEGORY_IMAGES[key];
    }
  });
}

