// ==========================================================================
// ADMIN AUTHENTICATION SYSTEM (Secure SHA-256 Hashing)
// ==========================================================================
const ADMIN_PASSWORD_HASHES = [
  "7f0f41b0591f755866b37a55a87a29b372d66e1bb3742cdb807d4750b10332e0",
  "a665a45920422f9d417e4867efdc4fb8a04a1f3fff1fa07e998e86f7f7a27ae3"
];

async function hashPassword(password) {
  const encoder = new TextEncoder();
  const data = encoder.encode(password);
  const hashBuffer = await crypto.subtle.digest("SHA-256", data);
  const hashArray = Array.from(new Uint8Array(hashBuffer));
  return hashArray.map(b => b.toString(16).padStart(2, "0")).join("");
}

function isAdminLoggedIn() {
  const session = sessionStorage.getItem("devwood_admin_session");
  if (!session) return false;
  try {
    const data = JSON.parse(session);
    return data.authenticated === true && data.timestamp && (Date.now() - data.timestamp < 24 * 60 * 60 * 1000);
  } catch (e) {
    return false;
  }
}

function setAdminSession() {
  sessionStorage.setItem("devwood_admin_session", JSON.stringify({
    authenticated: true,
    timestamp: Date.now()
  }));
}

function clearAdminSession() {
  sessionStorage.removeItem("devwood_admin_session");
}

async function verifyAdminPassword(password) {
  if (!password) return false;
  const trimmed = password.trim();
  try {
    const hash = await hashPassword(trimmed);
    const customHash = localStorage.getItem("devwood_admin_custom_hash");
    if (customHash && hash === customHash) {
      return true;
    }
    return ADMIN_PASSWORD_HASHES.includes(hash);
  } catch (e) {
    return false;
  }
}

async function changeAdminPassword(newPassword) {
  if (!newPassword || newPassword.trim().length < 4) {
    showToast("Password kam se kam 4 akshar ka hona chahiye!");
    return false;
  }
  const hash = await hashPassword(newPassword.trim());
  localStorage.setItem("devwood_admin_custom_hash", hash);
  showToast("Admin password safalta se update ho gaya!");
  return true;
}
window.changeAdminPassword = changeAdminPassword;

let _currentAdminLoginResolve = null;

function showAdminLoginModal() {
  return new Promise((resolve) => {
    _currentAdminLoginResolve = resolve;
    let modal = document.getElementById("adminLoginModal");
    if (!modal) {
      modal = document.createElement("div");
      modal.id = "adminLoginModal";
      modal.className = "modal-backdrop";
      modal.innerHTML = `
        <div class="modal-box" style="display: block; max-width: 440px; padding: 32px; position: relative;">
          <button type="button" class="modal-close-btn" id="adminLoginCloseBtn" style="position: absolute; top: 16px; right: 16px; background: rgba(0,0,0,0.06); border-radius: 50%; width: 36px; height: 36px; display: flex; align-items: center; justify-content: center; color: var(--wood-900); font-size: 1.1rem; z-index: 5;" title="Close">
            <i class="fa-solid fa-xmark"></i>
          </button>
          <div class="admin-login-header" style="text-align: center; margin-bottom: 22px;">
            <i class="fa-solid fa-shield-halved" style="font-size: 2.6rem; color: var(--gold-500); margin-bottom: 12px; display: inline-block;"></i>
            <h3 style="font-family: var(--font-serif); color: var(--wood-900); font-size: 1.6rem; margin: 0 0 6px 0;">Admin Panel Login</h3>
            <p style="color: var(--muted-text); font-size: 0.88rem; margin: 0;">Admin access ke liye password darj karein</p>
          </div>
          <form id="adminLoginForm">
            <div class="form-group" style="margin-bottom: 20px;">
              <label class="form-label" style="font-weight: 700; color: var(--wood-900); margin-bottom: 8px; display: flex; justify-content: space-between; align-items: center;">
                <span>Admin Password</span>
                
              </label>
              <div style="position: relative; width: 100%;">
                <input type="password" id="adminPasswordInput" class="form-control" placeholder="Admin password darj karein" autocomplete="current-password" required style="width: 100% !important; font-size: 1.25rem !important; letter-spacing: 3px !important; color: #1a100b !important; background: #ffffff !important; border: 2px solid var(--gold-500) !important; border-radius: 8px !important; padding: 12px 46px 12px 16px !important; text-align: left !important; font-weight: 700 !important; box-shadow: 0 2px 8px rgba(0,0,0,0.06) !important;">
                <button type="button" id="adminLoginEyeToggle" style="position: absolute; right: 12px; top: 50%; transform: translateY(-50%); background: none; border: none; color: #8c7355; cursor: pointer; font-size: 1.15rem; padding: 6px; display: flex; align-items: center; justify-content: center;" title="Show/Hide Password">
                  <i class="fa-solid fa-eye" id="adminEyeIcon"></i>
                </button>
              </div>
              <div style="margin-top: 6px; font-size: 0.78rem; color: var(--muted-text); display: flex; align-items: center; gap: 5px;">
                <i class="fa-solid fa-eye" style="color: var(--gold-600);"></i>
                <span>Password dekhne ke liye aankh wale icon par click karein</span>
              </div>
            </div>
            <div id="adminLoginError" style="color: #e74c3c; font-size: 0.88rem; margin-bottom: 16px; display: none; font-weight: 600; text-align: center; background: #fdf2f2; padding: 8px; border-radius: 6px; border: 1px solid #f8b4b4;"></div>
            <div style="display: flex; gap: 12px;">
              <button type="button" class="btn btn-outline" id="adminLoginCancelBtn" style="flex: 1; padding: 12px;">Cancel</button>
              <button type="submit" class="btn btn-gold" style="flex: 1; padding: 12px; font-weight: 700;">
                <i class="fa-solid fa-unlock"></i> Login Karein
              </button>
            </div>
          </form>
        </div>
      `;
      document.body.appendChild(modal);

      const cancelBtn = document.getElementById("adminLoginCancelBtn");
      const form = document.getElementById("adminLoginForm");
      const errorDiv = document.getElementById("adminLoginError");
      const input = document.getElementById("adminPasswordInput");
      const eyeToggle = document.getElementById("adminLoginEyeToggle");
      const eyeIcon = document.getElementById("adminEyeIcon");

      eyeToggle?.addEventListener("click", () => {
        if (input.type === "password") {
          input.type = "text";
          eyeIcon.className = "fa-solid fa-eye-slash";
        } else {
          input.type = "password";
          eyeIcon.className = "fa-solid fa-eye";
        }
      });

      const dismiss = (result) => {
        modal.classList.remove("active");
        if (input) {
          input.value = "";
          input.type = "password";
        }
        if (eyeIcon) eyeIcon.className = "fa-solid fa-eye";
        if (errorDiv) errorDiv.style.display = "none";
        if (_currentAdminLoginResolve) {
          const fn = _currentAdminLoginResolve;
          _currentAdminLoginResolve = null;
          fn(result);
        }
      };

      cancelBtn.addEventListener("click", () => dismiss(false));
      document.getElementById("adminLoginCloseBtn")?.addEventListener("click", () => dismiss(false));
      modal.addEventListener("click", (e) => {
        if (e.target === modal) dismiss(false);
      });

      form.addEventListener("submit", async (e) => {
        e.preventDefault();
        const password = input.value;
        if (!password) {
          errorDiv.textContent = "Password darj karein";
          errorDiv.style.display = "block";
          return;
        }
        const valid = await verifyAdminPassword(password);
        if (valid) {
          setAdminSession();
          updateAdminUI();
          showToast("Admin login safal!");
          dismiss(true);
        } else {
          errorDiv.textContent = "Galat password! Dobara koshish karein.";
          errorDiv.style.display = "block";
          input.value = "";
          input.focus();
        }
      });
    }

    const input = document.getElementById("adminPasswordInput");
    const errorDiv = document.getElementById("adminLoginError");
    if (input) {
      input.value = "";
      input.type = "password";
    }
    const eyeIcon = document.getElementById("adminEyeIcon");
    if (eyeIcon) eyeIcon.className = "fa-solid fa-eye";
    if (errorDiv) {
      errorDiv.style.display = "none";
      errorDiv.textContent = "";
    }

    modal.classList.add("active");
    setTimeout(() => document.getElementById("adminPasswordInput")?.focus(), 120);
  });
}

async function requireAdminAuth() {
  if (isAdminLoggedIn()) return true;
  const authorized = await showAdminLoginModal();
  return authorized;
}
window.showAdminLoginModal = showAdminLoginModal;
window.requireAdminAuth = requireAdminAuth;
window.requestAdminAuth = requireAdminAuth;


async function goToAdminPanel() {
  if (isAdminLoggedIn()) {
    window.location.href = "admin.html";
    return;
  }
  const authorized = await showAdminLoginModal();
  if (authorized) {
    window.location.href = "admin.html";
  }
}
window.goToAdminPanel = goToAdminPanel;

function logoutAdmin() {
  clearAdminSession();
  showToast("Admin logout ho gaye");
  updateAdminUI();
  if (window.location.pathname.includes("admin.html")) {
    window.location.href = "index.html";
  }
}

// Update UI based on admin status
function updateAdminUI() {
  const isAdmin = isAdminLoggedIn();
  document.querySelectorAll(".admin-only").forEach(el => {
    el.style.display = isAdmin ? "" : "none";
  });
  document.querySelectorAll(".admin-login-btn").forEach(el => {
    el.style.display = isAdmin ? "none" : "";
  });
  document.querySelectorAll(".admin-logout-btn").forEach(el => {
    el.style.display = isAdmin ? "" : "none";
  });
  document.querySelectorAll(".admin-panel-link").forEach(el => {
    el.style.display = isAdmin ? "inline-flex" : "none";
  });
}

// Protect admin functions
async function openAddProductModal(isEdit = false) {
  const authorized = await requireAdminAuth();
  if (!authorized) return;
  const modal = document.getElementById("addProductModal");
  if (modal) {
    if (!isEdit) {
      const form = document.getElementById("newProductForm");
      if (form) {
        form.reset();
        delete form.dataset.editId;
        const submitBtn = form.querySelector('button[type="submit"]');
        if (submitBtn) {
          submitBtn.innerHTML = '<i class="fa-solid fa-check"></i> Save & Publish Product';
        }
      }
      clearSelectedPhoto();
    }
    modal.classList.add("active");
  }
}
window.openAddProductModal = openAddProductModal;

// Helper: Category Icons for placeholder cards
function getCategoryIcon(cat) {
  if (!cat) return "fa-solid fa-couch";
  const c = cat.toLowerCase();
  if (c.includes("dining")) return "fa-solid fa-utensils";
  if (c.includes("bed")) return "fa-solid fa-bed";
  if (c.includes("mandir") || c.includes("temple")) return "fa-solid fa-place-of-worship";
  if (c.includes("living") || c.includes("sofa") || c.includes("diwan")) return "fa-solid fa-couch";
  if (c.includes("table") || c.includes("coffee") || c.includes("desk")) return "fa-solid fa-table";
  if (c.includes("wardrobe") || c.includes("storage") || c.includes("almirah") || c.includes("box")) return "fa-solid fa-warehouse";
  if (c.includes("wall") || c.includes("decor") || c.includes("jharokha")) return "fa-solid fa-archway";
  if (c.includes("door")) return "fa-solid fa-door-closed";
  if (c.includes("brass") || c.includes("chest") || c.includes("antique")) return "fa-solid fa-box-archive";
  if (c.includes("office") || c.includes("study")) return "fa-solid fa-briefcase";
  return "fa-solid fa-crown";
}

