async function deleteUserProduct(productId) {
  const authorized = await requireAdminAuth();
  if (!authorized) return;
  let userCustom = JSON.parse(localStorage.getItem("devwood_user_products") || "[]");
  userCustom = userCustom.filter(p => p.id !== productId);
  localStorage.setItem("devwood_user_products", JSON.stringify(userCustom));
  PRODUCTS = getProducts();
  showToast("Product safaltapoorvak hata diya gaya!");
  if (typeof window.renderAdminProducts === "function") {
    window.renderAdminProducts();
  }
  if (typeof window.updateAdminStats === "function") {
    window.updateAdminStats();
  }
  if (typeof window.refreshShopProducts === "function") {
    window.refreshShopProducts();
  }
}

// Combine Base Products with any Custom Products added by user
function getProducts() {
  try {
    const userCustom = JSON.parse(localStorage.getItem("devwood_user_products") || "[]");
    return [...userCustom, ...BASE_PRODUCTS];
  } catch (e) {
    return BASE_PRODUCTS;
  }
}

let PRODUCTS = getProducts();

