function closeAddProductModal() {
  const modal = document.getElementById("addProductModal");
  if (modal) modal.classList.remove("active");
  const form = document.getElementById("newProductForm");
  if (form) {
    form.reset();
    delete form.dataset.editId;
    const submitBtn = form.querySelector('button[type="submit"]');
    if (submitBtn) {
      submitBtn.innerHTML = '<i class="fa-solid fa-check"></i> Save & Publish Product';
    }
  }
  clearSelectedPhoto();
}
window.closeAddProductModal = closeAddProductModal;

// Gallery Photo Picker & Compression
function handleGalleryPhotoSelect(event) {
  const file = event.target.files && event.target.files[0];
  if (!file) return;

  const reader = new FileReader();
  reader.onload = function(e) {
    const img = new Image();
    img.onload = function() {
      // Compress with canvas to max 850px to ensure fast load and fit localStorage safely
      const canvas = document.createElement("canvas");
      let width = img.width;
      let height = img.height;
      const maxDim = 850;
      if (width > maxDim || height > maxDim) {
        if (width > height) {
          height = Math.round((height * maxDim) / width);
          width = maxDim;
        } else {
          width = Math.round((width * maxDim) / height);
          height = maxDim;
        }
      }
      canvas.width = width;
      canvas.height = height;
      const ctx = canvas.getContext("2d");
      ctx.drawImage(img, 0, 0, width, height);
      const compressedDataUrl = canvas.toDataURL("image/jpeg", 0.85);

      const base64Input = document.getElementById("newProdBase64");
      if (base64Input) base64Input.value = compressedDataUrl;

      const previewImg = document.getElementById("galleryPreviewImg");
      const previewWrap = document.getElementById("galleryUploadPreview");
      const promptWrap = document.getElementById("galleryUploadPrompt");

      if (previewImg) previewImg.src = compressedDataUrl;
      if (previewWrap) previewWrap.style.display = "flex";
      if (promptWrap) promptWrap.style.display = "none";
    };
    img.src = e.target.result;
  };
  reader.readAsDataURL(file);
}

function clearSelectedPhoto(event) {
  if (event) event.stopPropagation();
  const fileInput = document.getElementById("newProdGalleryFile");
  const base64Input = document.getElementById("newProdBase64");
  const previewWrap = document.getElementById("galleryUploadPreview");
  const promptWrap = document.getElementById("galleryUploadPrompt");

  if (fileInput) fileInput.value = "";
  if (base64Input) base64Input.value = "";
  if (previewWrap) previewWrap.style.display = "none";
  if (promptWrap) promptWrap.style.display = "block";
}

function handleAddNewProduct(event) {
  event.preventDefault();
  
  // Validation
  const name = document.getElementById("newProdName").value.trim();
  const subcategory = document.getElementById("newProdCategory").value;
  const price = parseInt(document.getElementById("newProdPrice").value);
  const woodType = document.getElementById("newProdWood").value.trim();
  
  if (!name) {
    showToast("Product ka naam darj karein");
    document.getElementById("newProdName").focus();
    return;
  }
  if (!subcategory) {
    showToast("Category select karein");
    return;
  }
  if (!price || price <= 0) {
    showToast("Sahi price darj karein");
    document.getElementById("newProdPrice").focus();
    return;
  }
  if (!woodType) {
    showToast("Wood type darj karein");
    document.getElementById("newProdWood").focus();
    return;
  }
  
  // Map subcategory to parent category
  const categoryMap = {
    "living": "furniture",
    "dining": "furniture",
    "bedroom": "furniture",
    "mandir": "furniture",
    "tables": "furniture",
    "storage": "furniture",
    "office": "furniture",
    "wall-decor": "antiques",
    "antiques": "antiques",
    "furniture": "furniture"
  };
  const category = categoryMap[subcategory] || "furniture";
  
  const originalPrice = parseInt(document.getElementById("newProdOldPrice").value) || Math.round(price * 1.2);
  const dimensions = document.getElementById("newProdDimensions").value.trim() || "Standard Size";
  
  // Gallery photo (Base64) or URL photo
  const galleryPhoto = document.getElementById("newProdBase64") ? document.getElementById("newProdBase64").value.trim() : "";
  const linkPhoto = document.getElementById("newProdImage") ? document.getElementById("newProdImage").value.trim() : "";
  const finalImage = galleryPhoto || linkPhoto || "";

  const desc = document.getElementById("newProdDesc").value.trim() || "Handcrafted with premium timber by Sardarshahar artisans.";

  const newProduct = {
    id: "user-" + Date.now(),
    name: name,
    category: category,
    subcategory: subcategory,
    price: price,
    originalPrice: originalPrice,
    badge: "New Arrival",
    isAntique: category === "antiques",
    woodType: woodType,
    dimensions: dimensions,
    finish: "Hand Wax Polish",
    rating: 5.0,
    reviewsCount: 1,
    image: finalImage,
    description: desc
  };

  try {
    const userProducts = JSON.parse(localStorage.getItem("devwood_user_products") || "[]");
    userProducts.unshift(newProduct);
    const dataToStore = JSON.stringify(userProducts);
    
    try {
      localStorage.setItem("devwood_user_products", dataToStore);
    } catch (storageError) {
      if (storageError.name === "QuotaExceededError" || storageError.code === 22) {
        showToast("Storage full! Purane products delete karein ya kam photos use karein.");
        return;
      }
      throw storageError;
    }
    
    // Refresh product list
    PRODUCTS = getProducts();
    
    showToast(`"${name}" product safaltapoorvak add ho gaya!`);
    closeAddProductModal();
    document.getElementById("newProductForm").reset();

    // Re-render if on shop page or home page
    if (typeof window.renderAdminProducts === "function") {
      window.renderAdminProducts();
    }
    if (typeof window.updateAdminStats === "function") {
      window.updateAdminStats();
    }
    if (typeof window.refreshShopProducts === "function") {
      window.refreshShopProducts();
    }
  } catch (e) {
    alert("Product save karne me error aaya: " + e.message);
  }
}

// ==========================================================================
// CART STATE MANAGEMENT
// ==========================================================================
let cart = [];

function initCart() {
  try {
    const savedCart = localStorage.getItem("devwood_cart");
    if (savedCart) {
      cart = JSON.parse(savedCart);
    }
  } catch (e) {
    console.error("Could not load cart from localStorage", e);
    cart = [];
  }
  updateCartBadge();
  renderCartDrawer();
}

function saveCart() {
  try {
    localStorage.setItem("devwood_cart", JSON.stringify(cart));
  } catch (e) {
    if (e.name === "QuotaExceededError" || e.code === 22) {
      showToast("Cart storage full! Kuch items hata de.");
      return;
    }
    console.error("Cart save error:", e);
  }
  updateCartBadge();
  renderCartDrawer();
}

function addToCart(productId) {
  const product = PRODUCTS.find(p => p.id === productId);
  if (!product) return;

  const existingIndex = cart.findIndex(item => item.id === productId);
  if (existingIndex > -1) {
    cart[existingIndex].qty += 1;
  } else {
    cart.push({
      id: product.id,
      name: product.name,
      price: product.price,
      image: product.image,
      woodType: product.woodType,
      qty: 1
    });
  }

  saveCart();
  showToast(`Added "${product.name}" to cart!`);
  openCartDrawer();
}

function updateQuantity(productId, delta) {
  const itemIndex = cart.findIndex(item => item.id === productId);
  if (itemIndex === -1) return;

  cart[itemIndex].qty += delta;
  if (cart[itemIndex].qty <= 0) {
    cart.splice(itemIndex, 1);
  }
  saveCart();
}

function removeFromCart(productId) {
  cart = cart.filter(item => item.id !== productId);
  saveCart();
  showToast("Item removed from cart.");
}

function updateCartBadge() {
  const totalCount = cart.reduce((sum, item) => sum + item.qty, 0);
  const badges = document.querySelectorAll(".cart-count-badge");
  badges.forEach(badge => {
    badge.textContent = totalCount;
    badge.style.display = totalCount > 0 ? "flex" : "none";
  });
}

function renderCartDrawer() {
  const container = document.getElementById("cartItemsList");
  const subtotalEl = document.getElementById("cartSubtotalAmount");
  if (!container || !subtotalEl) return;

  if (cart.length === 0) {
    container.innerHTML = `
      <div class="cart-empty-state">
        <i class="fa-solid fa-couch"></i>
        <h4>Your cart is empty</h4>
        <p>Explore our handcrafted furniture and rare antique collection.</p>
        <a href="shop.html" class="btn btn-gold" style="margin-top: 15px;">Browse Shop</a>
      </div>
    `;
    subtotalEl.textContent = `${STORE_CONFIG.currency}0`;
    return;
  }

  let subtotal = 0;
  container.innerHTML = cart.map(item => {
    const itemTotal = item.price * item.qty;
    subtotal += itemTotal;
    return `
      <div class="cart-item">
        ${item.image
          ? `<img src="${item.image}" alt="${item.name}" class="cart-item-img">`
          : `<div class="cart-item-placeholder"><i class="fa-solid fa-crown"></i></div>`
        }
        <div class="cart-item-details">
          <div class="cart-item-title">${item.name}</div>
          <div class="cart-item-price">${STORE_CONFIG.currency}${item.price.toLocaleString('en-IN')}</div>
          <div class="cart-qty-control">
            <button class="qty-btn" onclick="updateQuantity('${item.id}', -1)" title="Decrease">
              <i class="fa-solid fa-minus"></i>
            </button>
            <span class="qty-number">${item.qty}</span>
            <button class="qty-btn" onclick="updateQuantity('${item.id}', 1)" title="Increase">
              <i class="fa-solid fa-plus"></i>
            </button>
            <button class="cart-item-remove" onclick="removeFromCart('${item.id}')" title="Remove Item">
              <i class="fa-solid fa-trash-can"></i>
            </button>
          </div>
        </div>
      </div>
    `;
  }).join('');

  subtotalEl.textContent = `${STORE_CONFIG.currency}${subtotal.toLocaleString('en-IN')}`;
}

